    parent={}
    def find(a):
        while parent[a]!=a: parent[a]=parent[parent[a]]; a=parent[a]
        return a
    def union(a,b):
        ra,rb=find(a),find(b)
        if ra!=rb: parent[ra]=rb
    cs=set(cells)
    for c in cs: parent[c]=c
    for (i,j) in cs:
        for di_,dj_ in ([(1,0),(0,1)] if not diag else [(1,0),(0,1),(1,1),(1,-1)]):
            n=(i+di_,j+dj_)
            if n in cs: union((i,j),n)
    from collections import defaultdict
    d=defaultdict(list)
    for c in cs: d[find(c)].append(c)
    return list(d.values())
